<?php require dirname(__DIR__,2).'/app/bootstrap.php'; use App\Services\PasswordResetService; $token=$_GET['token']??$_POST['token']??'';$error=null;$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_verify($_POST['_csrf_token']??null))$error='Your form session expired. Please try again.';elseif(($_POST['password']??'')!==($_POST['password_confirmation']??''))$error='The password confirmation does not match.';elseif(!PasswordResetService::reset($token,$_POST['password']??''))$error='This recovery link is invalid, expired, or has already been used.';else $done=true;} ?><!doctype html><html><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="<?= e(asset('admin/assets/vendor/bootstrap/css/bootstrap.min.css')) ?>"><title>Choose a new password · ShopWise Kenya</title></head><body><main class="container py-5" style="max-width:480px"><div class="card"><div class="card-body p-4"><h1 class="h3">Choose a new password</h1><?php if($done): ?><div class="alert alert-success">Your password has been updated. You can now sign in.</div><a class="btn btn-primary" href="<?= e(url('admin/login.php')) ?>">Sign in</a><?php else: if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e($token) ?>"><label class="form-label">New password</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><label class="form-label">Confirm new password</label><input class="form-control mb-3" type="password" name="password_confirmation" minlength="8" required><button class="btn btn-primary">Update password</button></form><?php endif; ?></div></div></main></body></html>
